document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.char!==undefined){ci=+b.dataset.char;si=0;render()}if(b.dataset.set!==undefined){si=+b.dataset.set;render()}if(b.dataset.slot)editSlot(b.dataset.slot);if(b.dataset.gem!==undefined){editAlchemy(+b.dataset.gem)}if(b.dataset.edit){let k=b.dataset.edit,o=char()[k];if(k==='progress')editProgress();if(k==='bio')editBiologist();if(k==='pet')editPet();if(k==='alchemy')open('Alquimia',field('notes','Set ativo / notas',o.notes,'textarea'),v=>o.notes=v.notes)}if(b.id==='addchar'){if(readonly)return;data.characters.push(makeChar());ci=data.characters.length-1;si=0;save();$('#editChar').click()}if(b.id==='addset')newSet();if(b.id==='duplicateSet')duplicateSet();if(b.id==='deleteSet')deleteSet();if(b.id==='renameSet')renameSet();if(b.id==='editChar'){let c=char();open('Personagem',field('name','Nome',c.name)+field('class','Classe',c.class,'select',['Guerreiro','Ninja','Sura','Xamã','Lycan'])+field('doctrine','Doutrina',c.doctrine)+field('level','Nível',c.level,'number')+field('champion','Nível de campeão',c.champion,'number')+field('server','Servidor',c.server)+field('kingdom','Reino',c.kingdom,'select',['Shinsoo','Chunjo','Jinno']),v=>{if(!v.name.trim())throw Error('Introduz um nome.');Object.assign(c,v)},data.characters.length>1?()=>{data.characters.splice(ci,1);ci=0;si=0}:null)}if(b.id==='editStats')editStatus();if(b.id==='export'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='metin2-armory.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}if(b.id==='import')$('#importfile').click();if(b.id==='own')location.href=location.pathname;if(b.id==='share')share();if(b.id==='manageShares')ArmorySharing.manage()});
function validate(d){if(d.customCatalog!==undefined){if(!d.customCatalog||typeof d.customCatalog!=='object'||Array.isArray(d.customCatalog))throw Error('Catálogo inválido.');for(const e of Object.values(d.customCatalog)){if(!e||typeof e.label!=='string'||!e.label.trim()||![...slots,...extra].some(([k])=>k===e.slot)||!e.upgrades||typeof e.upgrades!=='object'||Array.isArray(e.upgrades)||Object.entries(e.upgrades).some(([k,v])=>!/^\d+$/.test(k)||typeof v!=='string'))throw Error('Entrada de catálogo inválida.');}}if(d.version!==1||!Array.isArray(d.characters)||!d.characters.length||!Array.isArray(d.items))throw Error('Ficheiro inválido.');for(let c of d.characters){if(!c.id||!c.name||!Array.isArray(c.sets)||!c.bio||!c.pet||!c.alchemy||![6,7].includes(c.alchemy.stones?.length))throw Error('Personagem inválida.');for(let s of c.sets)if(!s.stats||!s.items)throw Error('Set inválido.')}}
$('#importfile').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;let d=JSON.parse(await file.text());validate(d);if(confirm('Substituir os dados locais pelos deste ficheiro?')){normalizeData(d);data=d;ci=si=0;save();toast('Perfil importado.')}}catch{toast('Não foi possível importar este ficheiro.')}e.target.value=''};
async function share(source=char(),targetId){
 const c=structuredClone(source), ids=new Set(c.sets.flatMap(s=>Object.values(s.items)));
 const selected=data.items.filter(i=>ids.has(i.id)), customCatalog={};
 for(const [id,entry] of Object.entries(data.customCatalog||{}))if(selected.some(it=>JSON.stringify(it).includes(id)))customCatalog[id]=structuredClone(entry);
 const snapshot={version:1,characters:[c],items:structuredClone(selected),customCatalog};
 const bytes=new TextEncoder().encode(JSON.stringify(snapshot)), code=btoa(Array.from(bytes,b=>String.fromCharCode(b)).join(''));
 await ArmorySharing.create(snapshot,location.origin+location.pathname+'#view='+code,targetId);
}

