const iconOptions={'Lâmina Zodíaco':'zodiac-blade','Armadura de Aço Negro':'black-steel','Armadura Pata do Diabo':'devil-armor','Brincos de Esmeralda':'emerald-earrings','Brincos de Safira (nível 54)':'sapphire-earrings','Elmo de Dragão':'dragon-helmet','Cinto das Almas':'soul-belt','Talismã da Terra':'earth-talisman','Escudo Titã':'titan-shield','Sapatos de Fogo':'fire-shoes','Colar de Safira (nível 54)':'sapphire-necklace','Pulseira de Safira (nível 54)':'sapphire-bracelet','Roupa da Aura':'aura','Faixa Shen':'sash','Espada Venenosa':'poison-sword'};
const normalized=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function iconName(it){if(!it)return null;if(it.icon==='Colar de Safira')return 'sapphire-necklace';if(it.icon==='Pulseira de Safira')return 'sapphire-bracelet';if(it.icon&&iconOptions[it.icon])return iconOptions[it.icon];let n=normalized(it.name);const rules=[[/lamina.*zodiaco/,'zodiac-blade'],[/pata.*diabo/,'devil-armor'],[/aco negro/,'black-steel'],[/brincos.*safira/,'sapphire-earrings'],[/esmeralda/,'emerald-earrings'],[/elmo.*(dragao|escama)/,'dragon-helmet'],[/cinto.*almas/,'soul-belt'],[/talisma.*terra/,'earth-talisman'],[/escudo.*tita/,'titan-shield'],[/sapatos.*fogo/,'fire-shoes'],[/colar.*safira/,'sapphire-necklace'],[/pulseira.*safira/,'sapphire-bracelet'],[/aura/,'aura'],[/faixa.*shen/,'sash'],[/venenosa/,'poison-sword']];return rules.find(([re])=>re.test(n))?.[1]||null}
function equipmentIcon(it,k){if(k==='mount'&&mountEntry(it)?.image)return `<img class="game-icon" src="${esc(mountEntry(it).image)}" alt="">`;let icon=iconName(it),dynamic=it&&(imageUrl(it.customImage)||(it.icon&&it.icon!=='Automático'?'':imageUrl(catalogue()[catalogueId(it)]?.image)));const paths={weapon:'M19 4 22 7 10 24 14 28 11 31 7 27 3 31 1 29 5 25 2 22 5 19 9 22Z',armor:'M10 3 20 3 24 7 29 8 26 16 22 14 23 29 7 29 8 14 4 16 1 8 6 7Z',helmet:'M6 24V13Q6 3 16 3Q26 3 26 13V24L20 28 20 17 12 17 12 28Z',shield:'M5 5 16 2 27 5 26 20Q23 26 16 30Q9 26 6 20Z',earrings:'M7 5a5 5 0 1 0 1 0M23 5a5 5 0 1 0 1 0M8 15l-4 10 4 5 4-5ZM24 15l-4 10 4 5 4-5Z',talisman:'M16 2 27 16 16 30 5 16Z',bracelet:'M16 4a12 12 0 1 0 1 0M16 9a7 7 0 1 1-1 0',necklace:'M4 4Q4 24 16 27Q28 24 28 4M16 23l-4 5 4 4 4-4Z',shoes:'M5 3 13 3 13 19 17 23 17 29 2 29 2 24 5 20ZM20 3 28 3 28 19 31 23 31 29 19 29 19 23 20 20Z',belt:'M2 10H30V23H2ZM11 8H21V25H11ZM14 12H18V21H14',gloves:'M7 29 4 17 4 10 7 10 8 16 8 4 11 4 11 14 13 2 16 2 16 14 18 4 21 4 21 15 24 8 27 9 25 23 20 29Z'};return dynamic||icon?`<img class="game-icon" src="${esc(dynamic||'assets/'+icon+'.png')}" alt="" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="fallback" hidden>${silhouette(k,paths)}</span>`:silhouette(k,paths)}
function silhouette(k,paths){return `<svg class="silhouette" viewBox="0 0 32 34" aria-hidden="true"><path d="${paths[k]||'M16 2 29 16 16 30 3 16Z'}"/></svg>`}
function bonusContent(it){if(it.slot==='mount'){const e=mountEntry(it);return `<h3>${esc(it.name)}</h3><p>${it.mounted?'Montado · bónus ativos':'A pé · bónus inativos'}</p><div class="item-bonuses">${bonusMarkup(mountBonuses(it))}</div>${it.notes?`<p>${esc(it.notes)}</p>`:''}`;}it=effectiveAbsorption(it);return `<h3>${esc(it.name)} <span>${esc(itemUpgrade(it))}</span></h3>${fixedBlock(it)}${it.bonuses?`<div class="item-bonuses"><span class="bonus-section-label">Bónus normais</span>${bonusMarkup(it.bonuses)}</div>`:'<p class="no-bonuses">Sem bónus normais registados</p>'}${it.bonus6||it.bonus7?`<div class="rare-bonuses">${it.bonus6?`<div><span class="rare-label">6.º bónus</span>${bonusMarkup(it.bonus6)}</div>`:''}${it.bonus7?`<div><span class="rare-label">7.º bónus</span>${bonusMarkup(it.bonus7)}</div>`:''}</div>`:''}${it.stones?`<div class="item-stones">${stoneRows(it.stones)}</div>`:''}${it.notes?`<div class="item-notes">${esc(it.notes)}</div>`:''}`}
function renderBonuses(){if(!document.querySelector('#bonusList'))return;let rows=[...slots,...extra].map(([k,n])=>({k,n,it:item(set().items[k])})).filter(x=>x.it);$('#bonusList').innerHTML=rows.length?rows.map(({k,n,it})=>`<article class="bonus-card"><div class="bonus-card-icon">${equipmentIcon(it,k)}<small>${esc(n)}</small></div><div>${bonusContent(it)}</div></article>`).join(''):'<p class="hint">Os bónus aparecem aqui quando equipares os primeiros itens.</p>'}
