let activeSlot, tooltipPinned=false;
const touchEquipment=()=>window.matchMedia?.('(hover: none), (pointer: coarse)').matches || false;
function showTooltip(b,pinned=false){let it=item(set().items[b.dataset.slot]);if(!it){hideTooltip();return}hideTooltip();activeSlot=b;tooltipPinned=pinned;tooltip.classList.toggle('touch-tooltip',pinned);tooltip.setAttribute('role',pinned?'dialog':'tooltip');tooltip.setAttribute('aria-label','Atributos do equipamento');tooltip.innerHTML=bonusContent(it)+(pinned?'<div class="tooltip-actions">'+(!readonly?'<button type="button" data-tooltip-edit>Editar</button>':'')+'<button type="button" data-tooltip-close>Fechar</button></div>':'');tooltip.hidden=false;b.setAttribute('aria-describedby','itemTooltip');positionTooltip(b)}
function positionTooltip(b){const r=b.getBoundingClientRect(),w=tooltip.offsetWidth,h=tooltip.offsetHeight;let x=r.right+12;if(x+w>innerWidth-12)x=Math.max(12,r.left-w-12);let y=Math.min(Math.max(12,r.top),Math.max(12,innerHeight-h-12));tooltip.style.left=x+'px';tooltip.style.top=y+'px'}
function hideTooltip(){tooltipPinned=false;tooltip.classList.remove('touch-tooltip');tooltip.hidden=true;activeSlot?.removeAttribute('aria-describedby');activeSlot=null}
document.addEventListener('pointerover',e=>{const b=e.target.closest('[data-slot]');if(b&&e.pointerType!=='touch'&&!touchEquipment()&&!tooltipPinned)showTooltip(b)});
document.addEventListener('pointerout',e=>{const b=e.target.closest('[data-slot]');if(b&&!tooltipPinned&&!b.contains(e.relatedTarget))hideTooltip()});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-slot]')&&!touchEquipment()&&!tooltipPinned)showTooltip(e.target)});
document.addEventListener('click',e=>{
 const edit=e.target.closest('[data-tooltip-edit]'),close=e.target.closest('[data-tooltip-close]');
 if(edit||close){e.stopImmediatePropagation();const slot=activeSlot?.dataset.slot;hideTooltip();if(edit&&slot&&!readonly)editSlot(slot);return;}
 const b=e.target.closest('[data-slot]');
 if(b&&(touchEquipment()||e.pointerType==='touch')&&item(set().items[b.dataset.slot])){e.stopImmediatePropagation();if(tooltipPinned&&activeSlot===b)hideTooltip();else showTooltip(b,true);return;}
 if(tooltipPinned&&tooltip.contains(e.target))return;
 hideTooltip();
},true);
document.addEventListener('focusout',e=>{if(!tooltipPinned)hideTooltip()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTooltip()});window.addEventListener('resize',hideTooltip);window.addEventListener('scroll',e=>{if(!tooltipPinned||!tooltip.contains(e.target))hideTooltip()},true);hideTooltip();normalizeData(data);

function skillNames(c){const cl=String(c.class||'').toLowerCase(),d=String(c.doctrine||'').toLowerCase();if(cl==='sura'&&(d.includes('arma')||d.includes('weapon')))return ['Lâmina Encantada','Receio','Armadura Negra','Ataque do Dedo','Espiral do Dragão','Remover Efeito'];return []}
function normalizeData(d){for(const c of d.characters){if(!c.setsInitialized4){const keep=c.sets.filter(s=>!(['Relâmpagos','Vento','Yohara'].includes(s.name)&&!Object.keys(s.items).length&&Object.values(s.stats).every(v=>!Number(v))));if(keep.length)c.sets=keep;c.setsInitialized4=true;}for(const s of c.sets){s.stats.attackMax??=s.stats.attack||0;}c.pet.species??='Automático';c.progress??={horse:'',accuracy:'',skills:{},other:''};c.progress.skills??={};for(const n of skillNames(c))c.progress.skills[n]??='';}for(const it of d.items){if(!('bonus6' in it)&&!('bonus7' in it)){const lines=String(it.bonuses||'').split('\n');const eligible=['armor','helmet','shield','shoes','necklace','bracelet','earrings','talisman','gloves'];if(eligible.includes(it.slot)&&lines.length===7){it.bonuses=lines.slice(0,5).join('\n');it.bonus6=lines[5];it.bonus7=lines[6];}else if(it.slot==='weapon'&&lines.length===6&&/^Poder (do|da) /i.test(lines[0])){it.base=lines[0];it.bonuses=lines.slice(1).join('\n');}}it.base??='';it.bonus6??='';it.bonus7??='';if(!('absorbed' in it)){it.absorbed='';if(['sash','aura'].includes(it.slot)){it.absorbed=[it.base,it.bonuses].filter(Boolean).join('\n');it.base='';it.bonuses='';}}it.absorption??=it.slot==='sash'?(it.name.match(/(\d+(?:[.,]\d+)?)%/)?.[1]||''):'';it.absorbedFrom??='';it.fixedMode??='Automático';it.template??='Automático';it.fixedManual??='';}}
