function trainingIcon(name,raw){const level=exactSkillLevel(raw)||'',stage=level==='P'?3:level.startsWith('G')?2:level.startsWith('M')?1:0;return TRAINING_ICONS[name]?.[stage]||'';}
function renderProgress(){const c=char(),p=c.progress,calc=calculateStatus(),effects=calc.skillEffects;$('#progress').innerHTML=`<div class="training-summary"><div><img class="training-icon" src="assets/training-horse.png" alt=""><span>Nível do cavalo</span><strong>${esc(p.horse||'—')}</strong></div><div><img class="training-icon" src="assets/training-accuracy.png" alt=""><span>Precisão <small>+${PRECISION_VALUES[skillIndex(p.accuracy)]??'—'} precisão</small></span><strong>${esc(p.accuracy||'—')}</strong></div></div><div class="skill-list">${Object.entries(p.skills).map(([name,level])=>{const e=effects[name],active=set().statusEffects?.skillActive?.[name],description=name==='Lâmina Encantada'?(e?.attack===undefined?'Configura a INT base':`+${e.attack} ataque · ${e.steal}% absorção HP`):name==='Armadura Negra'?(e?.defense===undefined?'Configura a INT base':`+${e.defense} defesa`):name==='Receio'?`${e?.avoid??'—'}% evitar flechas · ${e?.reduction??'—'}% redução do ataque inimigo`:'Nível registado';return `<article class="training-skill ${active?'is-active':''}"><div class="training-skill-heading">${trainingIcon(name,level)?`<img class="training-icon" src="${trainingIcon(name,level)}" alt="">`:''}<span>${esc(name)}</span><strong class="skill-level ${exactSkillLevel(level)==='P'?'perfect':''}">${esc(level||'—')}</strong></div><p>${esc(description)}</p>${e?`<label class="skill-switch"><input type="checkbox" data-skill-active="${esc(name)}" ${active?'checked':''} ${!c.sets.length||(!e.k&&!active)?'disabled':''}> Contar no set</label>`:''}</article>`;}).join('')}</div>${p.other?`<p class="other-skills">${esc(p.other)}</p>`:''}`;}
function editProgress(){const c=char(),p=c.progress,names=Object.keys(p.skills);open('Skills e treino',field('horse','Nível do cavalo · 0–40',p.horse,'number')+skillLevelField('accuracy','Nível de Precisão',p.accuracy)+names.map((n,i)=>skillLevelField('skill_'+i,n,p.skills[n])).join('')+field('other','Outras skills / reforço / habilidade de campeão',p.other,'textarea'),v=>{if(v.horse!==''&&(!Number.isInteger(Number(v.horse))||Number(v.horse)<0||Number(v.horse)>40))throw Error('O nível do cavalo deve ficar entre 0 e 40.');const accuracy=readSkillLevel(v.accuracy,p.accuracy),skills=Object.fromEntries(names.map((n,i)=>[n,readSkillLevel(v['skill_'+i],p.skills[n])]));Object.assign(p,{horse:v.horse,accuracy,other:v.other,skills:{...p.skills,...skills}});});}
document.addEventListener('change',e=>{const name=e.target.dataset?.skillActive;if(!BUFF_SKILLS.includes(name)||!char().sets.length||!skillNames(char()).includes(name)||(e.target.checked&&!skillEffects(char(),calculateStatus().attributes)[name]?.k))return;const s=set();s.statusEffects={...s.statusEffects,skillActive:{...s.statusEffects?.skillActive,[name]:!!e.target.checked}};s.statusMode='auto';save();});
function alchemyIcon(g,i){const kinds=['ruby','diamond','jade','sapphire','garnet','onyx','amethyst'];const grade=normalized(g.grade);const classes=[/cru|brut|grezz/,/talhad|cortad|tagliat/,/rar/,/antig|antic/,/lendari|legend|leggend/,/mitic/];const clarities=[/translucid|opac/,/limpid|chiaro/,/impecav|perfett/,/brilhant|brillant/,/excelent|eccellent/];const cl=classes.findIndex(re=>re.test(grade));const clarity=clarities.findIndex(re=>re.test(grade));if(cl<0)return `<div class="empty-alchemy" aria-hidden="true">◇</div>`;let name='assets/alchemy-'+kinds[i]+'-'+cl+'-'+Math.max(0,clarity)+'.png';return `<img class="alchemy-icon" src="${name}" alt="${esc(g.name+' '+g.grade)}">`;}

function attackText(stats){const lo=Number(stats.attack||0),hi=Number(stats.attackMax??lo);return lo===hi?lo.toLocaleString('pt-PT'):lo.toLocaleString('pt-PT')+'–'+hi.toLocaleString('pt-PT');}
function fixedAttributes(it){if(it.fixedMode==='Manual')return {text:it.fixedManual||'',note:'',source:null};const id=it.catalogId&&catalogue()[it.catalogId]?it.catalogId:catalogueId(it),entry=catalogue()[id];const up=String(it.upgrade||'').match(/^\+?(\d+)$/)?.[1],text=entry?.upgrades?.[up];return {text:[text,it.fixedManual].filter(Boolean).join('\n'),note:entry?.refinement||'',source:text&&/^https?:\/\//.test(entry.source)?entry.source:null};}
