function stoneRows(text){return String(text).split('\n').filter(Boolean).map(line=>{const p=spiritMatch(line),image=p?window.STONE_IMAGES[p.name]:'';return `<div class="spirit-stone-row">${image?`<img src="${image}" alt="" class="spirit-icon">`:''}<span>${esc(line)}${spiritValue(p)?`<small class="stone-value">${esc(spiritValue(p))}</small>`:''}</span></div>`}).join('');}
function updateFixedPreview(){const box=$('#fixedPreview');if(!box||!$('#modal').open)return;let v=Object.fromEntries(new FormData($('#form')));let it={...v,slot:$('#form').dataset.slot||modalSlot(),refinedSockets:{material:v.refinedMaterial,count:Number(v.refinedCount||0)}};let attrs=fixedAttributes(it);box.innerHTML=`<div class="catalog-preview-icon">${equipmentIcon(it,it.slot)}</div><span class="bonus-section-label">Pré-visualização dos atributos fixos</span>${attrs.text?`<div>${bonusMarkup(attrs.text)}</div>`:'<p>Sem tabela confirmada para este melhoramento. Acrescenta a tabela deste equipamento no Catálogo.</p>'}${refinementBlock(it)}${attrs.source?`<a href="${esc(attrs.source)}" target="_blank" rel="noopener">Consultar tabela na wiki ↗</a>`:''}`;}
