function editAlchemy(i){const g=alchemyStones()[i],config=gemConfig(g),catalog=window.ALCHEMY_CATALOG[alchemyKinds[i]],picked=gemChoices(g,i);const options=['Nenhum',...Object.values(catalog.labels)];open(g.name,field('cl','Classe',config.cl<0?'Não equipada':alchemyClasses[config.cl],'select',['Não equipada',...alchemyClasses])+field('clarity','Clareza',alchemyClarities[Math.max(0,config.q)],'select',alchemyClarities)+field('lv','Melhoramento','+'+config.lv,'select',Array.from({length:7},(_,j)=>'+'+j))+selectPairs('available','Pedra disponível (tempo de uso)',g.available===false?'no':'yes',[['yes','Sim'],['no','Não · esgotada']])+'<div id="alchemyPreview" class="fixed-preview full"></div>'+[0,1,2].map(j=>field('bonus'+j,'Bónus variável '+(j+1),catalog.labels[picked[j]]||'Nenhum','select',options)).join('')+field('alchemyNotes','Notas / atributos anteriores não reconhecidos',gemNotes(g,i),'textarea'),v=>{const cl=alchemyClasses.indexOf(v.cl),q=alchemyClarities.indexOf(v.clarity),lv=Number(v.lv.slice(1));const entry=catalog.levels[cl+'-'+q+'-'+lv];const selected=[0,1,2].map(j=>Object.keys(catalog.labels).find(id=>catalog.labels[id]===v['bonus'+j])).filter(Boolean);if(cl>=0&&!entry)throw Error('Este melhoramento não está disponível para esta classe e clareza.');if(new Set(selected).size!==selected.length)throw Error('Escolhe bónus diferentes.');if(selected.length>[0,1,2,2,3,3][Math.max(0,cl)])throw Error('Demasiados bónus para esta classe.');if(selected.some(id=>!entry?.extra[id]))throw Error('Bónus indisponível nesta combinação.');if(v.available==='no')g.available=false;else delete g.available;g.grade=cl<0?'Não equipada':v.cl+' / '+v.clarity+' / '+v.lv;g.selectedBonuses=selected;g.alchemyNotes=v.alchemyNotes;if(!char().alchemy.stones[i])char().alchemy.stones[i]=g;});updateAlchemyPreview(i);$('#form').dataset.gemIndex=i;}
