function catalogue(){return {...window.ITEM_CATALOG,...(data.customCatalog||{})};}
function catalogueId(it){if(!it)return '';if(it.catalogId&&catalogue()[it.catalogId])return it.catalogId;const legacy=it.template&&it.template!=='Automático'?iconOptions[it.template]:iconName(it);if(legacy&&catalogue()[legacy])return legacy;return Object.entries(catalogue()).find(([,e])=>e.slot===it.slot&&normalized(e.label).replace(/[^a-z0-9]/g,'')===normalized(it.name).replace(/[^a-z0-9]/g,''))?.[0]||'';}
function selectPairs(k,label,value,options,full=false){return `<label class="${full?'full':''}">${esc(label)}<select name="${esc(k)}">${options.map(([id,name])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;}
function catalogueChoices(slot){return Object.entries(catalogue()).filter(([,e])=>e.slot===slot).sort((a,b)=>a[1].label.localeCompare(b[1].label,'pt')).map(([id,e])=>[id,e.label+(Object.keys(e.upgrades||{}).length||['sash','aura'].includes(e.slot)?'':' · stats manuais')]);}
function upgradeChoices(id,current='+0'){let entry=catalogue()[id],levels=Object.keys(entry?.upgrades||{});if(!levels.length)levels=Array.from({length:10},(_,i)=>String(i));let values=levels.map(n=>'+'+n).sort((a,b)=>Number(a.slice(1))-Number(b.slice(1)));if(current&&!values.includes(current))values.push(current);return values.map(v=>[v,v]);}
function imageUrl(url){const s=String(url||'');return /^assets\/[a-zA-Z0-9_.-]+\.png$/.test(s)||/^https?:\/\//.test(s)?s:'';}
function bonusOptions(slot,group){if(group==='inherent')return (window.BONUS_CATALOG.normal.weapon||[]).filter(e=>e.inherent);if(group==='normal'&&slot==='weapon')return window.BONUS_CATALOG.normal.weapon||[];if(['sash','aura'].includes(slot))return [];if(['costume','hair','skin'].includes(slot))return window.BONUS_CATALOG[group]?.[slot]||[];return window.BONUS_CATALOG[group]?.[slot]||[];}
function canonicalBonus(s){let n=normalized(s).replace(/[.:]/g,'').replace(/\s+/g,' ').trim();const aliases={'danos medio':'danos medios','dano medio':'danos medios','dano de habilidade':'danos de habilidades','dano de habilidades':'danos de habilidades','max hp':'max vd','max sp':'max mn','resistencia contra fogo':'resistencia ao fogo','resistencia contra gelo':'resistencia a gelo','resistencia contra vento':'resistencia ao vento','rapidez movimento':'rapidez de movimento','probabilidade de evitar flechas':'probabilidade de evitar flechas','regeneracao de hp':'regeneracao de vd','regeneracao de sp':'regeneracao de mn','furos':'probabilidade de golpes perfurantes','crit':'probabilidade de golpes criticos'};return (aliases[n]||n).replace(/^resistencia (?:contra |ao |a |aos |as )/,'resistencia ').replace(/relampagos/g,'raios');}
