function rollFields(prefix,title,line,options){const parsed=parseRoll(line,options),entry=options.find(e=>e.label===parsed.type);return `<div class="roll-row full" data-roll="${esc(prefix)}">${selectPairs(prefix+'_type',title,parsed.type,[['','Sem bónus'],...options.map(e=>[e.label,e.label]),['__custom','Personalizado']])}${selectPairs(prefix+'_value','Valor',parsed.value,[...(entry?.values||[]).map(v=>[v,v]),['__custom','Personalizado']])}${field(prefix+'_custom','Texto / valor personalizado',parsed.custom)}<input type="hidden" name="${prefix}_original" value="${esc(line||'')}"><input type="hidden" name="${prefix}_initial" value="${esc(JSON.stringify(parsed))}"></div>`;}
