function splitWeaponRolls(text){const options=bonusOptions('weapon','inherent'),inherent=[],normal=[];for(const line of String(text).split('\n')){if(options.some(e=>e.label===parseRoll(line,options).type)&&inherent.length<2)inherent.push(line);else normal.push(line);}return {inherent:inherent.join('\n'),normal:normal.join('\n')};}
function readWeaponRolls(v,split,original){const inherent=readRollGroup(v,'inherent',2),normal=readRollGroup(v,'normal',5);return inherent===split.inherent&&normal===split.normal?original:[inherent,normal].filter(Boolean).join('\n');}
function validateRollSelection(v,key,count,slot,group){const selected=[],options=bonusOptions(slot,group);for(let i=0;i<count;i++){const type=v[key+i+'_type'],value=v[key+i+'_value'];if(!type||type==='__custom')continue;const entry=options.find(e=>e.label===type);if(!entry)throw Error('Bónus incompatível com este slot.');if(value!=='__custom'&&!entry.values.includes(value))throw Error('Valor inválido para '+type+'.');if(selected.includes(type))throw Error('Escolhe bónus diferentes.');selected.push(type);}}

function absorptionFields(slot,old){const allowed=slot==='sash'?['weapon','armor']:['earrings','necklace','bracelet','shield'],src=old?.absorptionSource||{},id=src.catalogId||old?.absorbedCatalogId||'',choices=Object.entries(catalogue()).filter(([,e])=>allowed.includes(e.slot)).sort((a,b)=>a[1].label.localeCompare(b[1].label,'pt')).map(([id,e])=>[id,e.label]);return selectPairs('absorptionMode','Cálculo da absorção',src.enabled?'Automático':'Manual',[['Manual','Preservar valores atuais / manual'],['Automático','Calcular a partir do item original']])+selectPairs('absorbedCatalogId','Equipamento original',id,[['','Escolher equipamento'],...choices])+selectPairs('absorbedUpgrade','Melhoramento original',src.upgrade||old?.absorbedUpgrade||'+9',upgradeChoices(id,src.upgrade||'+9'))+'<div id="absAutoFields" class="full absorption-editor"><div class="absorption-origin-heading"><h3>Item original · antes da absorção</h3><p>Os bónus abaixo pertencem ao item sacrificado.</p></div><div id="absorptionSourceFields" class="full">'+absorptionSourceFields(id,src)+'</div><div class="absorption-result full"><h3>Resultado absorvido</h3><div id="absorptionPreview" class="fixed-preview full"></div></div><p class="hint full">Introduz os valores do equipamento original, antes da absorção. Alterna para Manual para editar os valores antigos. A absorção usa inteiros, com mínimo de 1 para atributos positivos. Imunidades mantêm-se.</p></div>'+hiddenField('absOriginal',JSON.stringify(src));}
function absorptionSourceFields(id,src={}){const slot=catalogue()[id]?.slot||'shield';return rollGroupFields('absNormal','Bónus normais originais · máximo 5', [src.inherent,src.normal].filter(Boolean).join('\n'),5,slot,'normal')+rollGroupFields('absRare6','6.º bónus original',src.bonus6||'',1,slot,'rare')+rollGroupFields('absRare7','7.º bónus original',src.bonus7||'',1,slot,'rare')+hiddenField('absFixed',src.fixed||'')+(slot==='weapon'?selectPairs('absElement','Elemento original',src.element||'',[['','Sem elemento'],...['Fogo','Gelo','Vento','Terra','Raios','Trevas'].map(x=>[x,x])])+field('absElementPower','Poder elemental original (%)',src.elementPower||'','number')+field('absElementAttack','Ataque elemental original (entre parênteses)',src.elementAttack||'','number'):'');}
function readAbsorptionSource(v,slot){const entry=catalogue()[v.absorbedCatalogId],allowed=slot==='sash'?['weapon','armor']:['earrings','necklace','bracelet','shield'];if(v.absorptionMode!=='Automático')return null;if(!entry||!allowed.includes(entry.slot))throw Error('Escolhe um equipamento original compatível.');const rate=Number(v.absorption);if(!(rate>0&&rate<=25))throw Error('A absorção deve estar entre 0 e 25%.');for(const [key,count,group] of [['absNormal',5,'normal'],['absRare6',1,'rare'],['absRare7',1,'rare']])if(group!=='inherent'||entry.slot==='weapon')validateRollSelection(v,key,count,entry.slot,group);if(!entry.upgrades?.[v.absorbedUpgrade.replace(/^\+/,'')]&&!v.absFixed?.trim())throw Error('Acrescenta uma tabela de atributos deste item no Catálogo.');for(const key of ['absElementPower','absElementAttack'])if(v[key]&&(!Number.isFinite(Number(v[key]))||Number(v[key])<0))throw Error('Valor elemental inválido.');const normal=readRollGroup(v,'absNormal',5);checkBonusCount(normal,5,JSON.parse(v.absOriginal||'null')?.normal);return {enabled:true,catalogId:v.absorbedCatalogId,upgrade:v.absorbedUpgrade,normal,inherent:'',bonus6:readRollGroup(v,'absRare6',1),bonus7:readRollGroup(v,'absRare7',1),fixed:v.absFixed||'',element:v.absElement||'',elementPower:v.absElementPower||'',elementAttack:v.absElementAttack||''};}
function absorbedInteger(value,rate){const n=Number(String(value).replace(',','.'));return n>0?Math.max(1,Math.floor(n*rate+1e-9)):n<0?Math.floor(n*rate+1e-9):0;}
function absorbText(text,rate){return String(text||'').split('\n').filter(l=>!/^Para n[ií]vel|^N[ií]vel/i.test(l)).map(line=>{let m=line.match(/^([+-]?\d+(?:[.,]\d+)?)(%)?\s+(.+)$/);if(m)line=m[3]+': '+m[1]+(m[2]||'');m=line.match(/^(.*?)(?:\s*:\s*|\s+)([+-]?\d+(?:[.,]\d+)?)(?:\s*[-–]\s*(\d+(?:[.,]\d+)?))?\s*(%)?$/);if(!m)return line;return m[1]+': '+absorbedInteger(m[2],rate)+(m[3]!==undefined?'-'+absorbedInteger(m[3],rate):'')+(m[4]||'');}).filter(Boolean).join('\n');}
function effectiveAbsorption(it){const src=it.absorptionSource;if(!src?.enabled)return it;const entry=catalogue()[src.catalogId],rate=Number(it.absorption)/100;if(!entry||!(rate>0))return it;const fixed=src.fixed||entry.upgrades?.[String(src.upgrade).replace(/^\+/,'')]||'',element=src.element&&Number(src.elementPower)>0?'Poder '+({Fogo:'do Fogo',Gelo:'do Gelo',Vento:'do Vento',Terra:'da Terra',Raios:'dos Raios',Trevas:'das Trevas'}[src.element])+': '+absorbedInteger(src.elementPower,rate)+'%':'',attack=Number(src.elementAttack)>0?'Valor de Ataque: '+absorbedInteger(src.elementAttack,rate):'';return {...it,absorbedFrom:entry.label+' '+src.upgrade,absorbed:[absorbText(fixed,rate),element,attack].filter(Boolean).join('\n'),bonuses:absorbText([src.inherent,src.normal].filter(Boolean).join('\n'),rate),bonus6:absorbText(src.bonus6,rate),bonus7:absorbText(src.bonus7,rate)};}
function updateAbsorptionPreview(){const box=$('#absorptionPreview');if(!box||!$('#modal').open)return;try{const v=Object.fromEntries(new FormData($('#form'))),src=readAbsorptionSource(v,$('#form').dataset.slot);box.innerHTML=src?bonusContent({name:'Resultado da absorção',slot:$('#form').dataset.slot,absorption:v.absorption,absorptionSource:src}):'Valores manuais preservados.';}catch(e){box.textContent=e.message;}}
document.addEventListener('change',e=>{if(e.target.name==='absorbedCatalogId'){const select=$('[name="absorbedUpgrade"]');select.innerHTML=upgradeChoices(e.target.value).map(([n])=>`<option>${n}</option>`).join('');$('#absorptionSourceFields').innerHTML=absorptionSourceFields(e.target.value);$('#absorptionSourceFields').querySelectorAll('[data-roll]').forEach(row=>syncRollRow(row));}if(e.target.closest('#form')){syncAbsorptionMode();updateAbsorptionPreview();updateElementalPreview();}});
document.addEventListener('input',e=>{if(e.target.closest('#form')){syncAbsorptionMode();updateAbsorptionPreview();updateElementalPreview();}});
function render(){renderProfile();renderCalculatedStatus();renderSetEffects();renderCombat();}
async function bootProfile(){
 if(!sharedBuildId){render();return;}
 document.body.classList.add('readonly');
 $('#notice').textContent='A carregar a personagem partilhada…';
 try{
  const snapshot=await ArmorySharing.load(sharedBuildId);validate(snapshot);normalizeData(snapshot);data=snapshot;readonly=true;ci=si=0;render();
 }catch(error){
  const section=document.querySelector('main>section');section.replaceChildren();
  const panel=document.createElement('article');panel.className='panel';
  const title=document.createElement('h1');title.textContent='Não foi possível abrir esta partilha';
  const reason=document.createElement('p');reason.textContent=error.message;
  const home=document.createElement('a');home.href=location.pathname;home.textContent='Voltar ao meu perfil';panel.append(title,reason,home);section.append(panel);
 }
}
bootProfile();

document.addEventListener('change',e=>{const m=e.target.name?.match(/^petSkill(?:Level)?([0-2])$/);if(!m)return;const i=m[1],n=$('[name="petSkill'+i+'"]').value,lv=$('[name="petSkillLevel'+i+'"]').value;$('[name="petSkillValue'+i+'"]').value=char().pet.skillValues?.[n+':'+lv]??'';});

document.addEventListener('change',e=>{if(['species','level','type'].includes(e.target.name)&&$('#form').querySelector('[data-pet-skill]')){$('#fields').querySelectorAll('[data-pet-skill]').forEach(row=>{row.querySelector('[name^="petSkillValue"]').value='';syncPetSkill(row);});}});

window.armoryShareCharacter=(id,targetId)=>{if(readonly)return false;const c=data.characters.find(c=>c.id===id);if(!c)return false;share(c,targetId);return true;};
